 "content": "def transform(grid):
    """Vertically align each non-background color's motif to color 8's top row."""
    h, w = len(grid), len(grid[0])
    rows = {c: [] for row in grid for c in row if c != 0}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                rows[value].append((r, c))
    if 8 not in rows:
        return [row[:] for row in grid]
    anchor_top = min(r for r, _ in rows[8])
    out = [[0] * w for _ in range(h)]
    for color, cells in rows.items():
        shift = anchor_top - min(r for r, _ in cells)
        for r, c in cells:
            rr = r + shift
            if 0 <= rr < h:
                out[rr][c] = color
    return out
